package application.domain.services.cart;
import application.domain.model.*; import application.domain.ports.in.*; import application.domain.ports.out.*; import application.domain.services.ServiceSupport; import java.util.*;
public class ManageWishlistService implements ManageWishlistUseCase { private final WishlistRepositoryPort wishlists; private final CustomerRepositoryPort customers; private final OperationAuditPort audit; public ManageWishlistService(WishlistRepositoryPort w,CustomerRepositoryPort c,OperationAuditPort a){wishlists=w;customers=c;audit=a;}
 public Wishlist manageWishlist(User actor,String cid,Product product,String operation){Customer c=ServiceSupport.required(customers.findById(cid),"Customer",cid);ServiceSupport.sameCustomer(actor,c);Wishlist w=wishlists.findByCustomer(c).orElseGet(()->wishlists.save(new Wishlist(c)));if("ADD".equalsIgnoreCase(operation))w.add(product);else if("REMOVE".equalsIgnoreCase(operation))w.remove(product);else if(!"LIST".equalsIgnoreCase(operation))throw new IllegalArgumentException("Unsupported wishlist operation");wishlists.update(w);audit.record(actor,"MANAGE_WISHLIST",cid,Map.of("operation",operation));return w;}
}
